package com.itu.gestionRH.entity.organization; import jakarta.persistence.*;
@Entity @Table(name="CONGE_SOLDE",uniqueConstraints=@UniqueConstraint(columnNames={"EMPLOYE_ID","ANNEE"})) public class CongeSolde{@Id @GeneratedValue(strategy=GenerationType.SEQUENCE,generator="congeSolde") @SequenceGenerator(name="congeSolde",sequenceName="SEQ_CONGE_SOLDE",allocationSize=1) Long id; @ManyToOne @JoinColumn(name="EMPLOYE_ID") Employe employe; Integer annee; double joursAcquis,joursUtilises,joursReportes; public Long getId(){return id;} public Employe getEmploye(){return employe;} public void setEmploye(Employe v){employe=v;} public Integer getAnnee(){return annee;} public void setAnnee(Integer v){annee=v;} public double getJoursAcquis(){return joursAcquis;} public void setJoursAcquis(double v){joursAcquis=v;} public double getJoursUtilises(){return joursUtilises;} public void setJoursUtilises(double v){joursUtilises=v;} public double getJoursReportes(){return joursReportes;} public void setJoursReportes(double v){joursReportes=v;} public double getDisponible(){return joursAcquis+joursReportes-joursUtilises;} }
